mapper.select:
SELECT T.* FROM (SELECT L.*, C.NAME, C.REMARK, F.NAME FILENAME, F.BIZCATEGORY, F.ID AS FILEID FROM T_CORE_REPORT_CONFIG_LINE L LEFT JOIN T_CORE_REPORT_CONFIG C ON L.REPORTCONFIGID = C.ID LEFT JOIN T_CORE_FILE F ON F.TARGETID = CONCAT('T_CORE_REPORT_CONFIG_LINE$', L.ID)
AND F.BIZCATEGORY = #{bizCategory}
WHERE 1 = 1) T
AND (EXISTS( SELECT 1 FROM T_CORE_USER_PERMISSION P WHERE P.TARGETID = TO_CHAR(T.ID) AND P.USERID=#{filter_userId})
OR EXISTS (SELECT 1 FROM T_CORE_ROLE_PERMISSION P WHERE P.PERMISSIONTYPEID = 'T_CORE_REPORT_CONFIG_LINE' AND P.ROLEID in
#{roleId}
AND P.TARGETID = TO_CHAR(T.ID) AND T.ACTIVATEDFLAG = '1')
)
AND (EXISTS( SELECT 1 FROM T_CORE_USER_PERMISSION P WHERE P.TARGETID = TO_CHAR(T.ID) AND P.USERID=#{filter_userId}) OR NOT EXISTS(SELECT 1 FROM T_CORE_USER_PERMISSION P WHERE P.TARGETID = TO_CHAR(T.ID)) OR EXISTS (SELECT 1 FROM T_CORE_ROLE_PERMISSION P WHERE P.PERMISSIONTYPEID = 'T_CORE_REPORT_CONFIG_LINE' AND P.ROLEID = #{loginUser.ext$.loginroleid} AND P.TARGETID = TO_CHAR(T.ID) AND T.ACTIVATEDFLAG = '1')
)
AND (T.MENUID IS NULL OR T.MENUID LIKE '%'||#{filter_menuId}||'%')
ORDER BY T.REPORTCONFIGID,
T.ORDERNO,T.ID
